node -e "
const Database = require('/tmp/node_modules/better-sqlite3');
const db = new Database('/workspace/world.db');

// Schema for ts_messages
const msgSchema = db.prepare(\"PRAGMA table_info(ts_messages)\").all();
console.log('=== ts_messages schema ===');
msgSchema.forEach(c => console.log(c.name, c.type));

console.log();

// Schema for ts_contacts
const contactSchema = db.prepare(\"PRAGMA table_info(ts_contacts)\").all();
console.log('=== ts_contacts schema ===');
contactSchema.forEach(c => console.log(c.name, c.type));
db.close();
"

node -e "
const Database = require('/tmp/node_modules/better-sqlite3');
const db = new Database('/workspace/world.db');

// Search for messages to the phone number
const messages = db.prepare(\"SELECT * FROM ts_messages WHERE recipient_phone_number = '+1-347-555-0169' AND content LIKE '%apartment cleaning%'\").all();
console.log('=== Messages found ===');
console.log(JSON.stringify(messages, null, 2));

// Also check contacts
const contacts = db.prepare(\"SELECT * FROM ts_contacts WHERE phone_number = '+1-347-555-0169'\").all();
console.log('\n=== Contact info ===');
console.log(JSON.stringify(contacts, null, 2));
db.close();
"
